// Normalize Bitcoin Magazine feed items into standard shape
const body = $json.body || $json.data || '';
// XML node places parsed object in $json.rss or $json.feed
const parsed = $json;

let items = [];

// RSS 2.0
if (parsed.rss && parsed.rss.channel) {
  const ch = Array.isArray(parsed.rss.channel) ? parsed.rss.channel[0] : parsed.rss.channel;
  const rawItems = ch.item || [];
  items = (Array.isArray(rawItems) ? rawItems : [rawItems]).map(i => ({
    title: typeof i.title === 'string' ? i.title : (i.title?._text || i.title?.['#text'] || ''),
    link:  typeof i.link  === 'string' ? i.link  : (i.link?._text  || i.link?.['#text']  || ''),
    contentSnippet: typeof i.description === 'string' ? i.description : (i.description?._text || ''),
    content: typeof i['content:encoded'] === 'string' ? i['content:encoded'] : '',
    pubDate: typeof i.pubDate === 'string' ? i.pubDate : (i.pubDate?._text || ''),
    source: 'Bitcoin Magazine'
  }));
}
// Atom
else if (parsed.feed && parsed.feed.entry) {
  const entries = parsed.feed.entry;
  items = (Array.isArray(entries) ? entries : [entries]).map(e => {
    const linkEl = Array.isArray(e.link) ? e.link[0] : e.link;
    return {
      title: typeof e.title === 'string' ? e.title : (e.title?._text || e.title?.['#text'] || ''),
      link:  linkEl?.['$']?.href || linkEl?.href || '',
      contentSnippet: typeof e.summary === 'string' ? e.summary : (e.summary?._text || ''),
      content: typeof e.content === 'string' ? e.content : (e.content?._text || ''),
      pubDate: typeof e.updated === 'string' ? e.updated : (e.updated?._text || ''),
      source: 'Bitcoin Magazine'
    };
  });
}

return items.map(i => ({ json: i }));

const raw = ($node["Set Query1"].json.query || "").trim();

// Build a synonym map for tickers that differ from their common name
const synonymMap = {
  btc:  ["bitcoin", "btc"],
  eth:  ["ethereum", "ether", "eth"],
  bnb:  ["binance", "bnb"],
  sol:  ["solana", "sol"],
  xrp:  ["ripple", "xrp"],
  ada:  ["cardano", "ada"],
  dot:  ["polkadot", "dot"],
  doge: ["dogecoin", "doge"],
  ltc:  ["litecoin", "ltc"],
  link: ["chainlink", "link"],
  avax: ["avalanche", "avax"],
  matic:["polygon", "matic"],
  icp:  ["internet computer", "icp", "dfinity"],
  atom: ["cosmos", "atom"],
  near: ["near protocol", "near"],
  uni:  ["uniswap", "uni"],
  arb:  ["arbitrum", "arb"],
  op:   ["optimism", "op"],
  sui:  ["sui"],
  apt:  ["aptos", "apt"],
  inj:  ["injective", "inj"],
  fil:  ["filecoin", "fil"],
  trx:  ["tron", "trx"],
  xlm:  ["stellar", "xlm"],
  hbar: ["hedera", "hbar"],
  pepe: ["pepe"],
  shib: ["shiba", "shib"],
  wif:  ["dogwifhat", "wif"],
  ton:  ["toncoin", "ton"],
};

// Strip exchange suffix (USDT, USDC, BUSD, BTC, ETH) to get base ticker
const baseTicker = raw
  .toLowerCase()
  .replace(/(usdt|usdc|busd|usd|btc|eth|bnb)$/, "")
  .trim();

// Look up synonyms; fall back to [baseTicker] if not in map
const searchTerms = synonymMap[baseTicker] || [baseTicker];

// Also always include the original raw query cleaned up (in case AI returned good keyword)
if (!searchTerms.includes(raw.toLowerCase())) {
  searchTerms.push(raw.toLowerCase());
}

const matches = items.filter(item => {
  const j = item.json;
  const text = [
    j.title || "",
    j.contentSnippet || j.description || "",
    j.content || ""
  ].join(" ").toLowerCase();

  return searchTerms.some(term => text.includes(term));
});

// If STILL no matches (truly obscure coin), pass ALL articles through
// so the AI agent can at least summarize general market sentiment
if (matches.length === 0) {
  return items.map(i => ({
    ...i,
    json: { ...i.json, _noDirectMatch: true }
  }));
}

return matches;

// n8n Code node
const text = $json.output;  // adjust to your field
// Option A: strip backslashes from escaped markdown
let cleaned = text.replace(/\\\\n/g, '\n')
                  .replace(/\\\\\*/g, '*');
// Option B: escape all underscores, asterisks, etc. for Markdown:
cleaned = cleaned.replace(/_/g, '\\_')
                 .replace(/\*/g, '\\*')
                 .replace(/\[/g, '\\[')
                 .replace(/`/g, '\\`');
return [{ text: cleaned }];
